import React from "react";
import "./StartupProjects.scss";
import {bigProjects} from "../../portfolio";
import {Fade} from "react-reveal";

export default function StartupProject() {
  function openProjectInNewWindow(url) {
    var win = window.open(url, "_blank");
    win.focus();
  }
  if (!bigProjects.display) {
    return null;
  }
  return (
    <Fade bottom duration={1000} distance="20px">
      <div className="main" id="projects">
        <div>
          <h1 className="skills-heading section-heading">
            {bigProjects.title}
          </h1>
          <p className="subTitle project-subtitle">{bigProjects.subtitle}</p>

          <Fade bottom cascade damping={0.08}>
            <div className="projects-container">
              {bigProjects.projects.map((project, i) => {
                return (
                  <div key={i} className="project-card project-card-light">
                    {project.image ? (
                      <div className="project-image">
                        <img
                          src={project.image}
                          alt={project.projectName}
                          className="card-image"
                        ></img>
                      </div>
                    ) : null}
                    <div className="project-detail">
                      <h5 className="card-title">{project.projectName}</h5>
                      <p className="card-subtitle">{project.projectDesc}</p>
                      {project.footerLink ? (
                        <div className="project-card-footer">
                          {project.footerLink.map((link, i) => {
                            return (
                              <span
                                key={i}
                                className="project-tag"
                                onClick={() => openProjectInNewWindow(link.url)}
                              >
                                {link.name}
                              </span>
                            );
                          })}
                        </div>
                      ) : null}
                    </div>
                  </div>
                );
              })}
            </div>
          </Fade>
        </div>
      </div>
    </Fade>
  );
}
